    uint256 public maxSupply;
    uint256 public maxWhitelistedAddresses;
    uint256 public currentSupply;
    bool public publicMintEnabled;
    bool public revealEnabled;
    string private baseURI;
    string private revealedBaseURI;
    mapping(address => bool) public whitelistedAddresses;

    event Whitelisted(address indexed addr, bool whitelisted);

    constructor(
        string memory _name,
        string memory _symbol,
        uint256 _maxSupply,
        uint256 _maxWhitelistedAddresses,
        uint256 _publicMintPrice,
        string memory _baseURI,
        string memory _revealedBaseURI,
        address _royaltyRecipient,
        uint96 _royaltyFeeNumerator
    ) ERC721(_name, _symbol) {
        publicMintPrice = _publicMintPrice;
        maxSupply = _maxSupply;
        maxWhitelistedAddresses = _maxWhitelistedAddresses;
        baseURI = _baseURI;
        revealedBaseURI = _revealedBaseURI;
        setRoyaltyInfo(_royaltyRecipient, _royaltyFeeNumerator);
    }

    modifier onlyWhitelisted() {
        require(whitelistedAddresses[msg.sender], "Not whitelisted");
        _;
    }

    modifier onlyWhenPublicMintEnabled() {
        require(publicMintEnabled, "Public minting is not enabled");
        _;
    }

    modifier onlyWhenRevealEnabled() {
        require(revealEnabled, "Reveal is not enabled");
        _;
    }

    function addToWhitelist(address[] memory _addresses) external onlyOwner {
        for (uint256 i = 0; i < _addresses.length; i++) {
            require(currentSupply + 1 <= maxWhitelistedAddresses, "Whitelist size exceeded");
            whitelistedAddresses[_addresses[i]] = true;
            emit Whitelisted(_addresses[i], true);
        }
    }

    function togglePublicMint() external onlyOwner {
        publicMintEnabled = !publicMintEnabled;
    }

    function toggleReveal() external onlyOwner {
        revealEnabled = !revealEnabled;
    }

    function setPublicMintPrice(uint256 _newPrice) external onlyOwner {
        publicMintPrice = _newPrice;
    }

    function setBaseURI(string memory _newBaseURI) external onlyOwner {
        baseURI = _newBaseURI;
    }

    function setRevealedBaseURI(string memory _newRevealedBaseURI) external onlyOwner {
        revealedBaseURI = _newRevealedBaseURI;
    }

    function _baseURI() internal view override(ERC721) returns (string memory) {
        return revealEnabled ? revealedBaseURI : baseURI;
    }

    function mintNFT() external payable whenNotPaused onlyWhenPublicMintEnabled {
        require(msg.value == publicMintPrice, "Insufficient funds");
        require(currentSupply + 1 <= maxSupply, "Max supply reached");
        currentSupply++;
        _safeMint(msg.sender, currentSupply);
    }

    function tokenURI(uint256 tokenId) public view virtual override(ERC721, ERC721URIStorage) returns (string memory) {
        require(_exists(tokenId), "ERC721Metadata: URI query for nonexistent token");
        return revealEnabled ? revealedBaseURI : baseURI;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    function withdraw() external onlyOwner {
        uint256 balance = address(this).balance;
        payable(owner()).transfer(balance);
    }

    // The following functions are overrides required by Solidity.

    function _burn(uint256 tokenId) internal override(ERC721, ERC721URIStorage) {
        super._burn(tokenId);
    }
}

