contract LendingPool {
    struct Market {
        address collateralToken;
        address borrowToken;
        uint256 borrowRate; // Annual borrow rate in basis points (e.g., 5000 = 50%)
        uint256 collateralRatio; // Collateralization ratio in basis points (e.g., 15000 = 150%)
    }

    mapping(address => Market) public markets;
    mapping(address => uint256) public depositBalances;
    mapping(address => uint256) public borrowBalances;

    event Deposit(address indexed user, address indexed collateralToken, uint256 amount);
    event Borrow(address indexed user, address indexed borrowToken, uint256 amount);
    event Repay(address indexed user, address indexed borrowToken, uint256 amount);

    function createMarket(
        address _collateralToken,
        address _borrowToken,
        uint256 _borrowRate,
        uint256 _collateralRatio
    ) public {
        require(markets[_collateralToken].collateralToken == address(0), "Market already exists");
        markets[_collateralToken] = Market({
            collateralToken: _collateralToken,
            borrowToken: _borrowToken,
            borrowRate: _borrowRate,
            collateralRatio: _collateralRatio
        });
    }

    function deposit(address _collateralToken, uint256 _amount) public {
        require(markets[_collateralToken].collateralToken != address(0), "Market does not exist");
        require(IERC20(_collateralToken).transferFrom(msg.sender, address(this), _amount), "Transfer failed");
        depositBalances[msg.sender][_collateralToken] += _amount;
        emit Deposit(msg.sender, _collateralToken, _amount);
    }

    function borrow(address _borrowToken, uint256 _amount) public {
        require(markets[_borrowToken].borrowToken != address(0), "Market does not exist");
        require(depositBalances[msg.sender][markets[_borrowToken].collateralToken] * 10000 >= _amount * markets[_borrowToken].collateralRatio, "Insufficient collateral");
        require(IERC20(_borrowToken).transfer(msg.sender, _amount), "Transfer failed");
        borrowBalances[msg.sender][_borrowToken] += _amount;
        emit Borrow(msg.sender, _borrowToken, _amount);
    }

    function repay(address _borrowToken, uint256 _amount) public {
        require(markets[_borrowToken].borrowToken != address(0), "Market does not exist");
        require(IERC20(_borrowToken).transferFrom(msg.sender, address(this), _amount), "Transfer failed");
        borrowBalances[msg.sender][_borrowToken] -= _amount;
        emit Repay(msg.sender, _borrowToken, _amount);
    }
}

interface IERC20 {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

