contract ConstantProductAMM {
    uint256 public constant FEE_DENOMINATOR = 10000;
    uint256 public k; // Invariant x * y = k

    address public tokenA;
    address public tokenB;

    mapping(address => uint256) public balances;

    constructor(address _tokenA, address _tokenB, uint256 _initialBalanceA, uint256 _initialBalanceB) {
        tokenA = _tokenA;
        tokenB = _tokenB;
        balances[msg.sender] = _initialBalanceA;
        balances[msg.sender] = _initialBalanceB;
        k = _initialBalanceA * _initialBalanceB;
    }

    function swap(uint256 inputAmount, address inputToken) external returns (uint256 outputAmount) {
        require(inputToken == tokenA || inputToken == tokenB, "Invalid input token");
        address outputToken = inputToken == tokenA ? tokenB : tokenA;

        uint256 inputBalance = balances[msg.sender][inputToken];
        uint256 outputBalance = balances[msg.sender][outputToken];

        require(inputBalance >= inputAmount, "Insufficient input balance");

        uint256 fee = (inputAmount * FEE_DENOMINATOR) / 1000; // 0.1% fee
        uint256 effectiveInput = inputAmount - fee;

        uint256 newInputBalance = inputBalance - effectiveInput;
        uint256 newOutputBalance = outputBalance + ((k / newInputBalance) - outputBalance);

        outputAmount = newOutputBalance - outputBalance;

        balances[msg.sender][inputToken] = newInputBalance;
        balances[msg.sender][outputToken] = newOutputBalance;

        // Transfer tokens
        IERC20(inputToken).transferFrom(msg.sender, address(this), effectiveInput);
        IERC20(outputToken).transfer(msg.sender, outputAmount);
    }

    function addLiquidity(uint256 inputA, uint256 inputB) external {
        require(inputA > 0 && inputB > 0, "Input amounts must be greater than zero");

        uint256 inputABalance = balances[msg.sender][tokenA];
        uint256 inputBBalance = balances[msg.sender][tokenB];

        uint256 totalInputA = inputABalance + inputA;
        uint256 totalInputB = inputBBalance + inputB;

        uint256 newK = totalInputA * totalInputB;
        uint256 liquidity = 0;

        if (newK > k) {
            liquidity = (inputA * totalInputB) / totalInputA;
        } else {
            liquidity = (inputB * totalInputA) / totalInputB;
        }

        k = newK;
        balances[msg.sender][tokenA] = totalInputA;
        balances[msg.sender][tokenB] = totalInputB;

        // Transfer tokens
        IERC20(tokenA).transferFrom(msg.sender, address(this), inputA);
        IERC20(tokenB).transferFrom(msg.sender, address(this), inputB);
    }
