    IVaultStrategy public strategy;

    uint256 public depositFee; // Basis points (100 = 1%)
    uint256 public withdrawalFee; // Basis points (100 = 1%)

    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event Harvested(uint256 amount);

    constructor(address _underlyingToken, address _strategy, uint256 _depositFee, uint256 _withdrawalFee) {
        underlyingToken = IERC20(_underlyingToken);
        strategy = IVaultStrategy(_strategy);
        depositFee = _depositFee;
        withdrawalFee = _withdrawalFee;
    }

    function setStrategy(address _strategy) external onlyOwner {
        strategy = IVaultStrategy(_strategy);
    }

