        require(_depositFee <= 10000, "Deposit fee must be <= 100%");
        require(_withdrawalFee <= 10000, "Withdrawal fee must be <= 100%");
        depositFee = _depositFee;
        withdrawalFee = _withdrawalFee;
    }

