        require(!recoveries[recoveryId].completed, "Recovery already completed");
        require(signatures.length >= requiredSignatures, "Not enough signatures");

        recoveries[recoveryId].signatures = signatures;
        recoveries[recoveryId].completed = true;

        emit RecoveryCompleted(recoveryId);
    }

    function isRecoveryCompleted(uint256 recoveryId) external view returns (bool) {
        return recoveries[recoveryId].completed;
    }
}

