    modifier notQueued(uint256 nonce) {
        require(queuedTransactions[nonce].eta == 0, "Transaction already queued");
        _;
    }

    modifier queued(uint256 nonce) {
        require(queuedTransactions[nonce].eta != 0, "Transaction not queued");
        _;
    }

    modifier ready(uint256 nonce) {
        require(block.timestamp >= queuedTransactions[nonce].eta, "Transaction not ready to execute");
        _;
    }

    function queueTransaction(address target, uint256 value, bytes memory data, uint256 delay) external onlyOwner notQueued(nextNonce) {
        uint256 eta = block.timestamp + delay;
        queuedTransactions[nextNonce] = QueuedTransaction(target, value, data, delay, eta);
        emit QueuedTransaction(nextNonce, target, value, data, delay, eta);
        nextNonce++;
    }

    function executeTransaction(uint256 nonce) external queued(nonce) ready(nonce) {
