pragma solidity ^0.8.0;

contract Timelock {
    struct QueuedTransaction {
        address target;
        uint256 value;
        bytes data;
        uint256 delay;
        uint256 eta;
    }

    address public owner;
    mapping(uint256 => QueuedTransaction) public queuedTransactions;
    uint256 public nextNonce;

    event QueuedTransaction(uint256 indexed nonce, address indexed target, uint256 value, bytes data, uint256 delay, uint256 eta);
    event ExecuteTransaction(uint256 indexed nonce);

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    modifier notQueued(uint256 nonce) {
        require(queuedTransactions[nonce].eta == 0, "Transaction already queued");
        _;
    }

    modifier queued(uint256 nonce) {
        require(queuedTransactions[nonce].eta != 0, "Transaction not queued");
        _;
    }

    modifier ready(uint256 nonce) {
        require(block.timestamp >= queuedTransactions[nonce].eta, "Transaction not ready to execute");
        _;
    }

    function queueTransaction(address target, uint256 value, bytes memory data, uint256 delay) external onlyOwner notQueued(nextNonce) {
        uint256 eta = block.timestamp + delay;
        queuedTransactions[nextNonce] = QueuedTransaction(target, value, data, delay, eta);
        emit QueuedTransaction(nextNonce, target, value, data, delay, eta);
        nextNonce++;
    }

    function executeTransaction(uint256 nonce) external queued(nonce) ready(nonce) {
        QueuedTransaction storage tx = queuedTransactions[nonce];
        delete queuedTransactions[nonce];

        (bool success, bytes memory returnData) = tx.target.call{value: tx.value}(tx.data);
        require(success, "Transaction execution failed");

        emit ExecuteTransaction(nonce);
    }
}

