import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract CrossChainBridge is AccessControl, ReentrancyGuard {
    using ECDSA for bytes32;

    bytes32 public constant ValidatorRole = keccak256("ValidatorRole");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    IERC20 public token;
    uint256 public rateLimit;
    uint256 public lastTransferTime;
    mapping(address => uint256) public lastTransferAmount;

    event Transfer(address indexed from, address indexed to, uint256 amount);
    event EmergencyPause(bool paused);
    event RateLimitUpdated(uint256 newRateLimit);

    constructor(address _token, uint256 _rateLimit) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ValidatorRole, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
        token = IERC20(_token);
        rateLimit = _rateLimit;
    }

    function transferToForeignChain(
        address receiver,
        uint256 amount,
        bytes calldata signature
    ) external nonReentrant {
        require(hasRole(ValidatorRole, msg.sender), "Not a validator");
        require(token.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        require(verifySignature(receiver, amount, signature), "Invalid signature");

        if (lastTransferTime + 1 minutes < block.timestamp) {
            lastTransferTime = block.timestamp;
            lastTransferAmount[msg.sender] = amount;
        } else {
            require(lastTransferAmount[msg.sender] + amount <= rateLimit, "Rate limit exceeded");
            lastTransferAmount[msg.sender] += amount;
        }

        emit Transfer(msg.sender, receiver, amount);
    }

    function burn(uint256 amount) external nonReentrant {
        require(token.transferFrom(msg.sender, address(this), amount), "Transfer failed");
        emit Transfer(msg.sender, address(0), amount);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
        emit EmergencyPause(true);
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
        emit EmergencyPause(false);
    }

    function updateRateLimit(uint256 newRateLimit) external onlyRole(ValidatorRole) {
        rateLimit = newRateLimit;
        emit RateLimitUpdated(newRateLimit);
    }

    function verifySignature(
        address receiver,
        uint256 amount,
        bytes memory signature
    ) internal pure returns (bool) {
