import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract WrappedToken is ERC20, Ownable {
    uint256 public feePercentage; // Fee percentage on unwrapping
    uint256 public totalFeesCollected; // Total fees collected
    mapping(address => uint256) public lastClaimTime; // Last claim time for long-term holders
    uint256 public constant claimCooldown = 365 days; // 1 year cooldown for claiming fees

    constructor(uint256 initialSupply, uint256 _feePercentage) ERC20("WrappedToken", "WTK") {
        _mint(msg.sender, initialSupply);
        feePercentage = _feePercentage;
    }

    // Function to unwrap tokens and collect fees
    function unwrap(uint256 amount) public {
        uint256 fee = calculateFee(amount);
        _transfer(msg.sender, address(this), fee); // Transfer fee to contract
        _transfer(msg.sender, msg.sender, amount); // Transfer unwrapped tokens to sender
        totalFeesCollected += fee;
    }

    // Function to calculate fee
    function calculateFee(uint256 amount) public pure returns (uint256) {
        return (amount * feePercentage) / 10000;
    }

    // Function to claim collected fees
    function claimFees() public {
        require(block.timestamp - lastClaimTime[msg.sender] >= claimCooldown, "Cooldown period not yet over");
        uint256 fees = calculateFeesEarned(msg.sender);
        _transfer(address(this), msg.sender, fees);
        lastClaimTime[msg.sender] = block.timestamp;
    }

    // Function to calculate fees earned by a holder
    function calculateFeesEarned(address holder) public view returns (uint256) {
        uint256 balance = balanceOf(holder);
        if (balance > 0 && block.timestamp - lastClaimTime[holder] >= claimCooldown) {
            return (balance * feePercentage) / 10000;
        }
        return 0;
    }

    // Function to set fee percentage (only by owner)
    function setFeePercentage(uint256 _feePercentage) public onlyOwner {
        feePercentage = _feePercentage;
    }

    // Function to withdraw collected fees (only by owner)
    function withdrawFees(uint256 amount) public onlyOwner {
        require(amount <= totalFeesCollected, "Insufficient funds");
        totalFeesCollected -= amount;
        _transfer(address(this), owner(), amount);
    }
}

